  const on = <K extends TaskflowEventType>(
    type: K,
    build: (payload: TaskflowEventPayload<K>) => Omit<ActivityRecordInput, "actorId" | "occurredAt">,
  ): Unsubscribe =>
    subscribe(type, (payload) =>
      record(payload.orgId, type as ActivityAction, {
        ...build(payload),
        actorId: payload.actorId,
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    );

  const offs: Unsubscribe[] = [
    on("project.created", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
      projectId: p.projectId,
      summary: `Created project ${p.name}`,
    })),
    on("project.updated", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
