    on("issue.updated", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Updated issue (${p.changedFields.join(", ")})`,
    })),
    on("issue.status_changed", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Status ${p.from} → ${p.to}`,
      metadata: { from: p.from, to: p.to },
