    build: (payload: TaskflowEventPayload<K>) => Omit<ActivityRecordInput, "actorId" | "occurredAt">,
  ): Unsubscribe =>
    subscribe(type, (payload) =>
      record(payload.orgId, type as ActivityAction, {
        ...build(payload),
        actorId: payload.actorId,
        occurredAt: payload.occurredAt,
      }).then(() => undefined),
    );

  const offs: Unsubscribe[] = [
    on("project.created", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
      projectId: p.projectId,
      summary: `Created project ${p.name}`,
    })),
    on("project.updated", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
      projectId: p.projectId,
      summary: `Updated project (${p.changedFields.join(", ")})`,
    })),
    on("project.archived", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
      projectId: p.projectId,
      summary: `Archived project with ${p.issuesArchived} issues`,
    })),
    on("project.restored", (p) => ({
      subjectKind: "project",
      subjectId: p.projectId,
      projectId: p.projectId,
      summary: "Restored project",
    })),
    on("issue.created", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Created issue "${p.title}"`,
      metadata: { priority: p.priority },
    })),
    on("issue.updated", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Updated issue (${p.changedFields.join(", ")})`,
    })),
    on("issue.status_changed", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Status ${p.from} → ${p.to}`,
      metadata: { from: p.from, to: p.to },
    })),
    on("issue.assigned", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: `Assigned to ${p.assigneeId}`,
      metadata: { assigneeId: p.assigneeId, previousAssigneeId: p.previousAssigneeId },
    })),
    on("issue.archived", (p) => ({
      subjectKind: "issue",
      subjectId: p.issueId,
      projectId: p.projectId,
      summary: "Archived issue",
    })),
    on("comment.created", (p) => ({
      subjectKind: "comment",
      subjectId: p.commentId,
      projectId: p.projectId,
      summary: `Commented on issue ${p.issueId}`,
    })),
    on("comment.updated", (p) => ({
      subjectKind: "comment",
      subjectId: p.commentId,
      projectId: p.projectId,
      summary: `Edited comment on issue ${p.issueId}`,
    })),
    on("comment.deleted", (p) => ({
      subjectKind: "comment",
      subjectId: p.commentId,
      projectId: p.projectId,
      summary: `Deleted comment on issue ${p.issueId}`,
    })),
    on("member.invited", (p) => ({
      subjectKind: "member",
      subjectId: p.email,
      projectId: null,
      summary: `Invited ${p.email} as ${p.role}`,
    })),
    on("member.joined", (p) => ({
      subjectKind: "member",
      subjectId: p.memberId,
      projectId: null,
      summary: `Joined as ${p.role}`,
    })),
    on("member.role_changed", (p) => ({
      subjectKind: "member",
      subjectId: p.memberId,
      projectId: null,
      summary: `Role ${p.from} → ${p.to}`,
    })),
    on("member.removed", (p) => ({
      subjectKind: "member",
      subjectId: p.memberId,
      projectId: null,
      summary: "Removed member",
    })),
    on("billing.plan_changed", (p) => ({
      subjectKind: "subscription",
      subjectId: p.orgId,
      projectId: null,
      summary: `Plan ${p.from} → ${p.to}`,
    })),
    on("flag.toggled", (p) => ({
      subjectKind: "feature_flag",
      subjectId: p.flag,
      projectId: null,
      summary: `Flag ${p.flag} ${p.enabled ? "enabled" : "disabled"}`,
      metadata: { enabled: p.enabled },
    })),
  ];

  return () => {
    for (const off of offs) off();
  };
}
'''
